:root{--bg:#f3f9ff;--card:#ffffff;--primary:#3ba4ff;--primary-dark:#1976d2;--accent:#20b486;--text:#1f2d3d;--muted:#6b7a90;--border:#d9ebfb;--shadow:0 10px 30px rgba(29,93,155,.08)}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--text);background:linear-gradient(135deg,#eef7ff 0%,#f9fcff 45%,#edf8ff 100%)}.app{display:grid;grid-template-columns:270px 1fr;gap:20px;min-height:100vh;padding:20px}.sidebar,.panel,.card,.auth-card{background:rgba(255,255,255,.92);border:1px solid var(--border);box-shadow:var(--shadow);border-radius:32px}.sidebar{padding:20px;position:sticky;top:20px;height:calc(100vh - 40px)}.brand{display:flex;gap:12px;align-items:center;margin-bottom:24px}.brand-badge{width:46px;height:46px;border-radius:16px;background:var(--primary);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;box-shadow:0 8px 20px rgba(59,164,255,.35)}.muted{color:var(--muted)}.tiny{font-size:12px}.nav-btn{width:100%;text-align:left;border:none;cursor:pointer;padding:14px 16px;border-radius:18px;background:transparent;margin-bottom:8px;font-size:15px;color:var(--text)}.nav-btn.active{background:var(--primary);color:#fff;font-weight:700}.nav-btn:hover{background:#eef7ff}.sidebar-note{margin:20px 0;padding:16px;border-radius:24px;background:#eef7ff;border:1px solid var(--border);font-size:14px;line-height:1.5}.content{display:flex;flex-direction:column;gap:20px}.panel,.card{padding:22px 24px}.panel-head{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.search-row,.actions,.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.row{justify-content:space-between}input,select,textarea{border:1px solid var(--border);border-radius:18px;padding:12px 14px;font-size:14px;outline:none;width:100%;background:#fff}textarea{min-height:110px;resize:vertical;margin:14px 0}.search{min-width:280px}.btn{border:none;cursor:pointer;border-radius:18px;padding:12px 16px;font-weight:700;font-size:14px}.btn-primary{background:var(--primary);color:#fff}.btn-primary:hover{background:var(--primary-dark)}.btn-success{background:var(--accent);color:#fff}.btn-outline{background:#fff;border:1px solid var(--border);color:var(--text)}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}.stat-value{font-size:28px;font-weight:700;margin:8px 0 4px}.grid-2{display:grid;grid-template-columns:1.35fr .95fr;gap:20px;margin-top:20px}.order{border:1px solid var(--border);border-radius:24px;padding:18px;margin-bottom:14px;background:#fff}.title{font-size:18px}.badge{display:inline-block;padding:8px 12px;border-radius:999px;font-size:12px;font-weight:700;background:#eef2f7;color:#506072}.status-Offen{background:#e3f2ff;color:#1f78c8}.status-In-Verhandlung{background:#fff3d6;color:#9a6700}.status-Vergeben{background:#dbf7ec;color:#06754f}.status-Abgeschlossen{background:#eceff3;color:#506072}.meta{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0;font-size:14px}.info-box{padding:14px;border-radius:18px;background:#f5fbff;border:1px solid var(--border);font-size:14px;line-height:1.5;margin:10px 0}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px}.msg,.timeline-item{padding:14px;border:1px solid var(--border);border-radius:18px;margin-bottom:10px;background:#f8fbff}.auth-wrap{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px}.auth-card{width:100%;max-width:460px;padding:28px}.auth-card input{margin-bottom:10px}.link-btn{border:none;background:transparent;color:var(--primary-dark);cursor:pointer;margin-top:12px;font-weight:700}@media(max-width:1200px){.stats{grid-template-columns:repeat(3,1fr)}.grid-2{grid-template-columns:1fr}}@media(max-width:900px){.app{grid-template-columns:1fr}.sidebar{position:static;height:auto}.meta,.two-col,.stats{grid-template-columns:1fr 1fr}}@media(max-width:640px){.meta,.two-col,.stats{grid-template-columns:1fr}.search{min-width:100%}}
